  S.sysKey = P.system+'|'+P.seed;
  const M=[];
  if (P.system==='fern'){
    M.push({p:.01,a:0,b:0,c:0,d:.16,e:0,f:0,v:0,col:.05});
    M.push({p:.85,a:.85,b:.04,c:0,d:-.04,e:.85,f:1.6,v:0,col:.34});
