  } else if (P.system==='dragon'){
    M.push({p:.5,a:.5,b:-.5,c:0,d:.5,e:.5,f:0,v:0,col:.18});
    M.push({p:.5,a:-.5,b:-.5,c:1,d:.5,e:-.5,f:0,v:0,col:.72});
    S.dom={x0:-.45,x1:1.25,y0:-.45,y1:1.05};
  } else { // 'flame' — curated contractive affines each with a pretty nonlinear variation
    const pretty=[1,3,4,6];               // sinusoidal, swirl, horseshoe, handkerchief (well-behaved, luminous)
    const k=3+(rnd()*2|0);                // 3 or 4 maps
    for (let i=0;i<k;i++){ const s=.42+rnd()*.36;   // contractive rows 0.42..0.78
