// --- rolling decay + running max (pass 1 over the grid) ---
const decay=0.86+P.persist*0.125;
const hist=S.hist, csum=S.csum;
let nMax=0;
for (let i=0;i<N4;i++){ const v=hist[i]*decay; hist[i]=v; csum[i]*=decay; if(v>nMax)nMax=v; }

