const expo=0.5+P.energy*2.2+K.pulse*0.22+A.rms*1.1;      // beat bump PARTIAL → no strobe
const invG=1/Math.max(0.3,P.gamma);
const logMax=Math.log(1+nMax*expo)+1e-3;
